  "You're on the leaderboard. Classmates see your first name, last initial and approved hours.": "Bạn đang ở trên bảng xếp hạng. Bạn cùng lớp thấy tên, chữ cái đầu của họ và số giờ được duyệt của bạn.",
  "Join to appear here. Only students at your school see it: your first name, last initial and approved hours.": "Tham gia để hiện ở đây. Chỉ học sinh cùng trường thấy: tên, chữ cái đầu của họ và số giờ được duyệt.",
