  "On. After a month you logged hours, we'll email you on the 1st with what you logged and how close you are to your goal.": "Đang bật. Sau tháng bạn có ghi giờ, ngày 1 chúng tôi sẽ email những gì bạn đã ghi và bạn còn cách mục tiêu bao xa.",
