  "Places {org} works with. Hours you serve at them count toward your goals.": "Những nơi {org} hợp tác. Giờ bạn phục vụ ở đó được tính vào mục tiêu.",
  "Places your school works with. Hours you serve at them count toward your goals.": "Những nơi trường bạn hợp tác. Giờ bạn phục vụ ở đó được tính vào mục tiêu.",
