  "Could not load your children's hours": "Không tải được giờ của con bạn",
  "The server did not answer. Your child's hours are safe — this page just could not fetch them.": "Máy chủ không phản hồi. Giờ của con bạn vẫn an toàn, chỉ là trang này chưa lấy được.",
  "Ask your child for their link code — they'll find it in Settings → Family — then enter it to follow their hours.": "Hãy xin con mã liên kết (trong Cài đặt → Gia đình), rồi nhập vào để theo dõi giờ của con.",
  "The organizer's waiver: approving also agrees to it for your child": "Giấy miễn trừ của người tổ chức: đồng ý cũng là đồng ý thay cho con bạn",
  "Set a target and we'll track your progress toward it. The primary goal powers your dashboard ring.": "Đặt mục tiêu, chúng tôi sẽ theo dõi tiến độ. Mục tiêu chính hiển thị trên vòng tiến độ ở bảng điều khiển.",
  "Your logged hours are stored on this device. If you've created an account, some features above (Family sharing, school linking, cross-device sync, two-factor authentication) also store data on our server. Sign out below to clear your session.": "Số giờ bạn ghi được lưu trên thiết bị này. Nếu bạn đã tạo tài khoản, một số tính năng ở trên (chia sẻ gia đình, liên kết trường, đồng bộ thiết bị, xác thực hai yếu tố) cũng lưu dữ liệu trên máy chủ của chúng tôi. Đăng xuất bên dưới để xóa phiên.",
  "Passkey added. You can use it the next time you sign in.": "Đã thêm khóa truy cập. Bạn có thể dùng ở lần đăng nhập tới.",
  "Passkey removed.": "Đã xóa khóa truy cập.",
  "Passkeys": "Khóa truy cập",
  "After your password, confirm it’s you with Face ID, Touch ID, your fingerprint or your device PIN instead of typing a code. Keep your authenticator app too — its backup codes are how you get back in if you lose every device with a passkey.": "Sau mật khẩu, xác nhận đó là bạn bằng Face ID, Touch ID, vân tay hoặc mã PIN thiết bị thay vì gõ mã. Vẫn giữ ứng dụng xác thực: mã dự phòng của nó là cách vào lại nếu bạn mất mọi thiết bị có khóa truy cập.",
  "Added {date}": "Thêm ngày {date}",
  "last used {date}": "dùng lần cuối {date}",
  "This device can’t create passkeys.": "Thiết bị này không tạo được khóa truy cập.",
  "Add a passkey": "Thêm khóa truy cập",
  "If you lose this device, sign in with one of these instead of your passkey. Each works once, and this is the only time they're shown.": "Nếu mất thiết bị này, hãy đăng nhập bằng một trong các mã này thay cho khóa truy cập. Mỗi mã dùng một lần, và đây là lần duy nhất chúng được hiển thị.",
