  "Students enter this in Settings → Join school to link themselves to you, or use the join link in the starter kit below.": "Học sinh nhập mã này trong Cài đặt → Tham gia trường để liên kết với bạn, hoặc dùng liên kết tham gia trong bộ tài liệu khởi đầu bên dưới.",
  "Transfer requests ({n})": "Yêu cầu chuyển trường ({n})",
  "These students asked to move to your school. Their volunteer record moves with them.": "Những học sinh này xin chuyển đến trường bạn. Hồ sơ tình nguyện của họ chuyển theo.",
