  "Invite student": "Mời học sinh",
  "Invite a student by email": "Mời học sinh qua email",
  "They get an email and accept in their Settings. You'll see them in your student list once they do. Students can also join with your school code.": "Họ nhận email và chấp nhận trong Cài đặt. Bạn sẽ thấy họ trong danh sách học sinh sau khi họ chấp nhận. Học sinh cũng có thể tham gia bằng mã trường.",
  "Invite sent. They'll appear once they accept.": "Đã gửi lời mời. Họ sẽ xuất hiện khi chấp nhận.",
  "Students ({n})": "Học sinh ({n})",
