  "No grade": "Chưa có lớp",
  "Hour reports": "Báo cáo giờ",
  "Export every student's logged hours for a date range — for administrators, service-hour compliance, or grant reporting.": "Xuất số giờ đã ghi của mọi học sinh theo khoảng ngày, cho quản trị viên, tuân thủ giờ phục vụ hoặc báo cáo tài trợ.",
  "Volunteer hours report": "Báo cáo giờ tình nguyện",
