  "Let students sign in with your school's Google or Microsoft account instead of a VolunTrack password.": "Cho học sinh đăng nhập bằng tài khoản Google hoặc Microsoft của trường thay vì mật khẩu VolunTrack.",
  "Custom domain": "Tên miền riêng",
  "Serve VolunTrack to your students on your own web address instead of the shared one.": "Cung cấp VolunTrack cho học sinh tại địa chỉ web của riêng bạn thay vì địa chỉ chung.",
  "Put your school's logo and colour on the sign-in page students see at your own web address.": "Đặt logo và màu của trường lên trang đăng nhập học sinh thấy tại địa chỉ web riêng.",
  "Add a co-admin": "Thêm đồng quản trị viên",
  "Co-admins can review uploads, manage students, and send announcements — {n}/10 used.": "Đồng quản trị viên có thể xem tài liệu tải lên, quản lý học sinh và gửi thông báo; đã dùng {n}/10.",
  "You've reached the limit of 10 co-admins. Remove one below to add another.": "Bạn đã đạt giới hạn 10 đồng quản trị viên. Gỡ một người bên dưới để thêm người khác.",
  "Temporary password (min 8 chars)": "Mật khẩu tạm (tối thiểu 8 ký tự)",
  "Add co-admin": "Thêm đồng quản trị viên",
  "Co-admins ({n})": "Đồng quản trị viên ({n})",
  "No co-admins added yet.": "Chưa thêm đồng quản trị viên nào.",
  "Make main admin": "Đặt làm quản trị viên chính",
  "Remove co-admin": "Gỡ đồng quản trị viên",
  "New principal?": "Hiệu trưởng mới?",
  "Hand this school’s main account to the person taking over. They get an email to accept and set their own password. You stay on as a co-admin until they remove you, and you’ll be signed out when they accept.": "Chuyển tài khoản chính của trường cho người tiếp quản. Họ nhận email để chấp nhận và đặt mật khẩu riêng. Bạn vẫn là đồng quản trị viên cho đến khi họ gỡ bạn, và sẽ bị đăng xuất khi họ chấp nhận.",
  "Post a volunteer task": "Đăng nhiệm vụ tình nguyện",
