  "Location — where it happens": "Địa điểm: diễn ra ở đâu",
  "Important info — only shown to approved volunteers (e.g. what to bring, parking, contact details)": "Thông tin quan trọng: chỉ hiện cho tình nguyện viên được duyệt (vd: cần mang gì, chỗ đỗ xe, thông tin liên hệ)",
  "Phone number — shown to approved volunteers": "Số điện thoại: hiện cho tình nguyện viên được duyệt",
