  "No volunteer tasks yet.": "Chưa có nhiệm vụ tình nguyện nào.",
  "No PDFs yet.": "Chưa có PDF nào.",
  "Sent back:": "Bị trả lại:",
  "Requirements saved.": "Đã lưu yêu cầu.",
  "Loading requirements…": "Đang tải yêu cầu…",
  "Schools you assign to this template follow these sections instead of your defaults. A section left unset here uses your defaults, and a school can still set its own.": "Các trường bạn gán cho mẫu này sẽ theo các phần này thay vì mặc định của bạn. Phần nào để trống ở đây sẽ dùng mặc định, và trường vẫn có thể tự đặt.",
  "Every rule here applies to the students linked to your school. Anything you leave inherited follows your organization, or VolunTrack’s defaults if you have none.": "Mọi quy định ở đây áp dụng cho học sinh liên kết với trường bạn. Phần nào để kế thừa sẽ theo tổ chức của bạn, hoặc mặc định của VolunTrack nếu không có.",
  "These are the defaults for every school you own. A school that sets its own version of a section keeps it — your changes reach the rest.": "Đây là mặc định cho mọi trường bạn sở hữu. Trường nào tự đặt phiên bản riêng của một phần sẽ giữ phần đó; thay đổi của bạn áp dụng cho các trường còn lại.",
  "Inherit": "Kế thừa",
  "Set our own": "Tự đặt",
  "Set in this template": "Đặt trong mẫu này",
  "Set a default": "Đặt mặc định",
