  "Allow future-dated entries": "Cho phép mục ghi ngày tương lai",
  "Minimum hours per entry": "Số giờ tối thiểu mỗi mục ghi",
  "No minimum": "Không tối thiểu",
  "Maximum hours per entry": "Số giờ tối đa mỗi mục ghi",
