  "Log within N days of the activity": "Ghi trong vòng N ngày sau hoạt động",
  "Any time after": "Bất cứ lúc nào sau đó",
  "Minimum description length": "Độ dài mô tả tối thiểu",
  "Students can’t add, edit or delete entries dated before this, e.g. once a semester’s report is done. You can still add hours for them.": "Học sinh không thể thêm, sửa hoặc xóa mục ghi trước ngày này, ví dụ sau khi xong báo cáo học kỳ. Bạn vẫn có thể thêm giờ cho các em.",
  "Allowed categories": "Danh mục được phép",
  "Leave all unchecked to accept every category.": "Để trống tất cả để chấp nhận mọi danh mục.",
  "One per line. Hours from anywhere else still go in, but they're flagged in Students → Hours to check so you can look at them first. Leave empty to accept every place.": "Mỗi dòng một nơi. Giờ ở nơi khác vẫn được ghi nhưng được đánh dấu trong Học sinh → Giờ cần kiểm tra để bạn xem trước. Để trống để chấp nhận mọi nơi.",
  "Total hours required": "Tổng số giờ yêu cầu",
  "None": "Không có",
  "Grades at your school": "Các lớp ở trường bạn",
  "Tick the grades you have, e.g. only 9th, or 10th–12th. Students then pick from these, must pick one to join, and “New school year” moves your top grade on. Leave all unticked to allow any grade.": "Tích các lớp trường bạn có, vd chỉ lớp 9, hoặc lớp 10–12. Học sinh sẽ chọn trong số này, phải chọn một để tham gia, và “Năm học mới” sẽ chuyển lớp cao nhất lên. Để trống để cho phép mọi lớp.",
  "Note to students": "Lời nhắn cho học sinh",
  "Due before senior year begins.": "Hạn chót trước khi bắt đầu năm cuối cấp.",
  "Per-grade overrides": "Ghi đè theo lớp",
  "A student in one of these grades is held to its number instead of the total above.": "Học sinh thuộc một trong các lớp này phải đạt số giờ của lớp thay vì tổng ở trên.",
  "Minimum hours by type": "Số giờ tối thiểu theo loại",
  "At least this many of a student’s hours must be of one type. They count toward the total, not on top of it.": "Ít nhất bấy nhiêu giờ của học sinh phải thuộc một loại. Số giờ này tính vào tổng, không cộng thêm.",
  "Add a type": "Thêm loại",
