  "Add a level": "Thêm cấp",
  "Hours count the same way as your requirement: everything logged except rejected entries.": "Số giờ được tính giống như yêu cầu: mọi thứ đã ghi trừ mục bị từ chối.",
  "New signer: the old signature was removed. Draw theirs below, or use the phone QR code.": "Người ký mới: chữ ký cũ đã bị xóa. Vẽ chữ ký của họ bên dưới hoặc dùng mã QR điện thoại.",
  "What each entry needs": "Mỗi mục ghi cần gì",
  "Who signs": "Ai ký",
  "Students sign on the Log Hours form before they can save.": "Học sinh ký trên biểu mẫu Ghi giờ trước khi lưu.",
  "Students must name a supervisor, who gets an emailed link and signs there to approve.": "Học sinh phải ghi tên người giám sát; người đó nhận liên kết qua email và ký ở đó để duyệt.",
  "Students sign on the form, and their supervisor signs on the emailed link to approve.": "Học sinh ký trên biểu mẫu, và người giám sát ký trên liên kết qua email để duyệt.",
  "Link to your form": "Liên kết đến biểu mẫu của bạn",
  "Google Form — students fill it in right on the Log Hours page, then tick a box to say they sent it.": "Google Form: học sinh điền ngay trên trang Ghi giờ, rồi tích ô xác nhận đã gửi.",
  "A Google Form opens right on the Log Hours page. Any other link (a PDF, a doc) is something students download, get signed, and upload. Leave blank if they get the form in class.": "Google Form sẽ mở ngay trên trang Ghi giờ. Liên kết khác (PDF, tài liệu) là thứ học sinh tải về, xin ký rồi tải lên. Để trống nếu các em nhận biểu mẫu trên lớp.",
  "This looks like the link for editing the form. Use Send → link in Google Forms instead, so students can fill it in.": "Đây có vẻ là liên kết để sửa biểu mẫu. Hãy dùng Gửi → liên kết trong Google Forms để học sinh điền được.",
  "Short forms.gle links can’t open inside VolunTrack. Paste the full docs.google.com link to keep students on the page.": "Liên kết rút gọn forms.gle không mở được trong VolunTrack. Hãy dán liên kết đầy đủ docs.google.com để học sinh ở lại trang.",
  "Note to students (optional)": "Lời nhắn cho học sinh (không bắt buộc)",
  "Your supervisor must sign in blue or black ink.": "Người giám sát phải ký bằng mực xanh hoặc đen.",
  "Advisor name": "Tên giáo viên phụ trách",
  "Answer type": "Kiểu trả lời",
  "Choices": "Lựa chọn",
  "First period, Second period, Third period": "Tiết 1, Tiết 2, Tiết 3",
