  "Helper text (optional)": "Chữ hướng dẫn (không bắt buộc)",
  "Add a question": "Thêm câu hỏi",
  "{n} schools — {k} of them override at least one section.": "{n} trường, {k} trường ghi đè ít nhất một phần.",
