  "The new principal gets an email to accept and becomes the main admin of {school}. The current one stays as a co-admin and is signed out.": "Hiệu trưởng mới nhận email để chấp nhận và trở thành quản trị viên chính của {school}. Người hiện tại vẫn là đồng quản trị viên và bị đăng xuất.",
  "Loading invites…": "Đang tải lời mời…",
  "No invites sent": "Chưa gửi lời mời nào",
