  "Expired": "Đã hết hạn",
  "Someone new running the organization?": "Có người mới điều hành tổ chức?",
  "Hand this organization’s account to them. They get an email to accept and set their own password. When they do, this login is removed from the organization and signed out.": "Chuyển tài khoản của tổ chức cho họ. Họ nhận email để chấp nhận và đặt mật khẩu riêng. Khi họ chấp nhận, thông tin đăng nhập này bị gỡ khỏi tổ chức và đăng xuất.",
  "They'll get an email with a link to set their own password and school code. The link expires in 3 days.": "Họ sẽ nhận email có liên kết để đặt mật khẩu và mã trường riêng. Liên kết hết hạn sau 3 ngày.",
