  "Branding saved. Sign-in pages on your domain pick it up within 10 minutes.": "Đã lưu thương hiệu. Trang đăng nhập trên tên miền của bạn sẽ cập nhật trong 10 phút.",
  "Loading branding…": "Đang tải thương hiệu…",
  "Accent colour": "Màu nhấn",
  "A hex value. Used for accents on your sign-in page — not for text or button backgrounds, so any colour stays readable. Leave blank for the VolunTrack green.": "Giá trị hex. Dùng cho điểm nhấn trên trang đăng nhập, không dùng cho chữ hay nền nút, nên màu nào cũng dễ đọc. Để trống để dùng màu xanh VolunTrack.",
  "Enter a hex value like #2f855a.": "Nhập giá trị hex như #2f855a.",
  "Preview": "Xem trước",
  "Save branding": "Lưu thương hiệu",
  "This branding applies to your organization’s own hostnames. Each school brands its own separately.": "Thương hiệu này áp dụng cho các tên miền riêng của tổ chức. Mỗi trường đặt thương hiệu riêng.",
  "Only your school’s sign-in page changes. The VolunTrack name and logo stay on the canonical site.": "Chỉ trang đăng nhập của trường bạn thay đổi. Tên và logo VolunTrack vẫn giữ trên trang chính.",
  "Branding only appears on your own hostname. You don’t have a live domain yet — set one up under Custom domain first, then anything you save here shows on its sign-in page.": "Thương hiệu chỉ hiện trên tên miền riêng của bạn. Bạn chưa có tên miền hoạt động; hãy thiết lập trong Tên miền riêng trước, rồi những gì lưu ở đây sẽ hiện trên trang đăng nhập.",
  "Shown at sign-in on": "Hiển thị khi đăng nhập tại",
  "Set how many hours your students need (one total, or per grade) to see who is behind.": "Đặt số giờ học sinh cần (một tổng, hoặc theo lớp) để xem ai đang chậm.",
