  "Say why, so the student can fix it.": "Hãy nói lý do để học sinh sửa.",
  "Entries no supervisor or event organizer has confirmed. They count for now; approve them, or send one back with a reason and it stops counting until the student fixes it.": "Các mục ghi chưa có người giám sát hay người tổ chức sự kiện xác nhận. Hiện vẫn được tính; hãy duyệt, hoặc trả lại kèm lý do và mục đó ngừng được tính cho đến khi học sinh sửa.",
  "All ({n})": "Tất cả ({n})",
