  "Summary PDF": "PDF tóm tắt",
  "This range hit the {n}-row limit, so the export is incomplete. Narrow the dates and run it again.": "Khoảng này chạm giới hạn {n} dòng nên bản xuất chưa đầy đủ. Thu hẹp ngày rồi chạy lại.",
  "Showing 25 of {n}. The exports contain every student.": "Đang hiện 25/{n}. Bản xuất có mọi học sinh.",
  "Loading domains…": "Đang tải tên miền…",
  "Custom domains can be claimed and their ownership verified, but this server cannot issue certificates yet, so a domain cannot go live. Contact VolunTrack support.": "Có thể nhận và xác minh tên miền riêng, nhưng máy chủ này chưa cấp được chứng chỉ nên tên miền chưa hoạt động được. Hãy liên hệ hỗ trợ VolunTrack.",
  "Ownership verified": "Đã xác minh quyền sở hữu",
