  "{n}% off — for referring {name}": "Giảm {n}%: vì đã giới thiệu {name}",
  "{n}% off — for referring a new customer": "Giảm {n}%: vì đã giới thiệu khách hàng mới",
  "1 discount waiting": "1 khoản giảm giá đang chờ",
  "Applied to your next invoice.": "Áp dụng cho hóa đơn tiếp theo.",
  "Rule sets": "Bộ quy định",
  "Your defaults apply to every school. Add a template, such as “Middle schools”, for schools that need different rules, then assign those schools to it below.": "Mặc định của bạn áp dụng cho mọi trường. Thêm mẫu, như “Trường THCS”, cho các trường cần quy định khác, rồi gán các trường đó bên dưới.",
  "Defaults (all schools)": "Mặc định (mọi trường)",
