  "Add template": "Thêm mẫu",
  "Delete “{name}” (its schools go back to your defaults)": "Xóa “{name}” (các trường của mẫu sẽ quay về mặc định)",
  "Which rules each school follows": "Mỗi trường theo quy định nào",
  "Defaults": "Mặc định",
  "Compare schools": "So sánh các trường",
  "Hours this year": "Giờ năm nay",
  "Met requirement": "Đã đạt yêu cầu",
  "No requirement": "Không có yêu cầu",
