  "Start a group challenge": "Bắt đầu thử thách nhóm",
  "A shared goal for all your students, like “500 hours together by Dec 1”. Everyone sees one progress bar fill up as anyone logs hours.": "Mục tiêu chung cho mọi học sinh, như “Cùng nhau 500 giờ trước 1/12”. Mọi người thấy một thanh tiến độ đầy dần khi có người ghi giờ.",
  "Fall food drive": "Quyên góp thực phẩm mùa thu",
